StructuredTextModel.Text:
CASE TyrblåserState OF 
	
	10: 	// En tyrblåser eller flere i auto. 
	IF TyrBlåser1Pri = 1 OR Tyrblåser2Pri = 1 THEN 
		Pri1OK := TRUE; 
					ELSIF
						IF TyrBlåser1Pri = 2 OR Tyrblåser2Pri = 2 THEN 
							PRI2OK := TRUE; 
						ELSIF
								Tyrblåser1_BM01 = 3 THEN 
								TyrBlåser1Pri := 2; 
						ELSIF Tyrblåser1_BM02 = 3 THEN 
						Tyrblåser1_BM02 := 2;
						
						END_IF;
